import { useState } from "react";
import NoteContext from "./noteContext";

const NoteState = (props) => {
  const host = "http://localhost:5000";
  const notesInitial = []

  const [notes, setNotes] = useState(notesInitial);
  const [isInitialized, setIsInitialized] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedTag, setSelectedTag] = useState("");
  const [sortBy, setSortBy] = useState("dateCreated");
  const [undoStack, setUndoStack] = useState([]);
  const [redoStack, setRedoStack] = useState([]);
  const [noteStats, setNoteStats] = useState({ totalNotes: 0, totalWords: 0, totalCharacters: 0 });

  // Calculate note statistics
  const calculateStats = (notesList) => {
    const totalNotes = notesList.length;
    const totalWords = notesList.reduce((acc, note) => {
      const words = (note.title + " " + note.description).trim().split(/\s+/).length;
      return acc + (note.title || note.description ? words : 0);
    }, 0);
    const totalCharacters = notesList.reduce((acc, note) => {
      return acc + (note.title?.length || 0) + (note.description?.length || 0);
    }, 0);
    
    setNoteStats({ totalNotes, totalWords, totalCharacters });
  };

  // Undo/Redo functionality
  const saveToUndoStack = (action, data) => {
    setUndoStack(prev => [...prev, { action, data, timestamp: Date.now() }]);
    setRedoStack([]); // Clear redo stack when new action is performed
  };

  const undo = () => {
    if (undoStack.length === 0) return;
    
    const lastAction = undoStack[undoStack.length - 1];
    setUndoStack(prev => prev.slice(0, -1));
    setRedoStack(prev => [...prev, lastAction]);
    
    // Implement undo logic based on action type
    switch (lastAction.action) {
      case 'ADD':
        setNotes(prev => prev.filter(note => note._id !== lastAction.data._id));
        break;
      case 'DELETE':
        setNotes(prev => [...prev, lastAction.data]);
        break;
      case 'UPDATE':
        setNotes(prev => prev.map(note => 
          note._id === lastAction.data.id ? lastAction.data.oldNote : note
        ));
        break;
      default:
        break;
    }
  };

  const redo = () => {
    if (redoStack.length === 0) return;
    
    const actionToRedo = redoStack[redoStack.length - 1];
    setRedoStack(prev => prev.slice(0, -1));
    setUndoStack(prev => [...prev, actionToRedo]);
    
    // Implement redo logic
    switch (actionToRedo.action) {
      case 'ADD':
        setNotes(prev => [...prev, actionToRedo.data]);
        break;
      case 'DELETE':
        setNotes(prev => prev.filter(note => note._id !== actionToRedo.data._id));
        break;
      case 'UPDATE':
        setNotes(prev => prev.map(note => 
          note._id === actionToRedo.data.id ? actionToRedo.data.newNote : note
        ));
        break;
      default:
        break;
    }
  };

  // Get unique tags from all notes
  const getAllTags = () => {
    const tags = notes.flatMap(note => 
      note.tag ? note.tag.split(',').map(tag => tag.trim()) : []
    );
    return [...new Set(tags)].filter(tag => tag);
  };

  // Filter and search notes
  const getFilteredNotes = () => {
    let filteredNotes = [...notes];
    
    // Apply search filter
    if (searchTerm) {
      filteredNotes = filteredNotes.filter(note => 
        note.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        note.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (note.tag && note.tag.toLowerCase().includes(searchTerm.toLowerCase()))
      );
    }
    
    // Apply tag filter
    if (selectedTag) {
      filteredNotes = filteredNotes.filter(note => 
        note.tag && note.tag.toLowerCase().includes(selectedTag.toLowerCase())
      );
    }
    
    // Apply sorting
    filteredNotes.sort((a, b) => {
      switch (sortBy) {
        case 'dateCreated':
          return new Date(b.date || b.createdAt) - new Date(a.date || a.createdAt);
        case 'dateModified':
          return new Date(b.updatedAt || b.date) - new Date(a.updatedAt || a.date);
        case 'alphabetical':
          return a.title.localeCompare(b.title);
        case 'alphabeticalDesc':
          return b.title.localeCompare(a.title);
        default:
          return 0;
      }
    });
    
    return filteredNotes;
  };

  //fetch a note
  const getNotes = async() => {
    try {
      const token = localStorage.getItem('token');
      if (!token) {
        console.error('No token found');
        setNotes([]);
        return;
      }

      const response = await fetch(`${host}/api/notes/fetchallnotes`, {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        }
      });
      
      const json = await response.json();
      console.log('getNotes response:', json);
      
      if (response.ok) {
        let notesList = [];
        if (Array.isArray(json)) {
          notesList = json;
        } else if (json.notes && Array.isArray(json.notes)) {
          notesList = json.notes;
        } else {
          notesList = [];
        }
        setNotes(notesList);
        calculateStats(notesList);
        setIsInitialized(true);
      } else {
        console.error('Failed to fetch notes:', json);
        setNotes([]);
        setIsInitialized(true);
      }
    } catch (error) {
      console.error('Error fetching notes:', error);
      setNotes([]);
      setIsInitialized(true);
    }
  }

  //Add a note
  const addNote = async(title, description, tag, attachments = [], images = [], todoItems = []) => {
    try {
      const token = localStorage.getItem('token');
      if (!token) {
        console.error('No token found');
        return;
      }

      const response = await fetch(`${host}/api/notes/addnote`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        },
        body: JSON.stringify({
          title, 
          description, 
          tag, 
          attachments, 
          images, 
          todoItems,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString()
        }),
      });
      
      const note = await response.json();
      
      if (response.ok) {
        const newNotes = [...notes, note];
        setNotes(newNotes);
        calculateStats(newNotes);
        saveToUndoStack('ADD', note);
        return true;
      } else {
        console.error('Failed to add note:', note);
        return false;
      }
    } catch (error) {
      console.error('Error adding note:', error);
      return false;
    }
  };

  //Delete a Note
  const deleteNote = async(id) => {
    try {
      const token = localStorage.getItem('token');
      if (!token) {
        console.error('No token found');
        return;
      }

      // Find the note before deleting for undo functionality
      const noteToDelete = notes.find(note => note._id === id);

      const response = await fetch(`${host}/api/notes/deletenote/${id}`, {
        method: "DELETE",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token,
        }
      });
      
      if (response.ok) {
        const newNotes = notes.filter((note) => note._id !== id);
        setNotes(newNotes);
        calculateStats(newNotes);
        if (noteToDelete) {
          saveToUndoStack('DELETE', noteToDelete);
        }
      } else {
        const json = await response.json();
        console.error('Failed to delete note:', json);
      }
    } catch (error) {
      console.error('Error deleting note:', error);
    }
  };

  //Update a note
  const editNote = async (id, title, description, tag, attachments = [], images = [], todoItems = []) => {
    try {
      const token = localStorage.getItem('token');
      if (!token) {
        console.error('No token found');
        return;
      }

      // Find the old note for undo functionality
      const oldNote = notes.find(note => note._id === id);

      const response = await fetch(`${host}/api/notes/updatenote/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          "auth-token": token
        },
        body: JSON.stringify({
          title, 
          description, 
          tag, 
          attachments, 
          images, 
          todoItems,
          updatedAt: new Date().toISOString()
        }),
      });
      
      if (response.ok) {
        let newNotes = JSON.parse(JSON.stringify(notes))
        for (let index = 0; index < newNotes.length; index++) {
          const element = newNotes[index];
          if (element._id === id) {
            const updatedNote = {
              ...newNotes[index],
              title,
              description,
              tag,
              attachments,
              images,
              todoItems,
              updatedAt: new Date().toISOString()
            };
            newNotes[index] = updatedNote;
            
            // Save to undo stack
            if (oldNote) {
              saveToUndoStack('UPDATE', { id, oldNote, newNote: updatedNote });
            }
            break;
          }
        }
        setNotes(newNotes);
        calculateStats(newNotes);
      } else {
        const json = await response.json();
        console.error('Failed to update note:', json);
      }
    } catch (error) {
      console.error('Error updating note:', error);
    }
  };

  // Duplicate a note
  const duplicateNote = async (note) => {
    const duplicatedNote = {
      ...note,
      title: `${note.title} (Copy)`,
      _id: undefined // Remove ID so backend creates new one
    };
    
    return await addNote(
      duplicatedNote.title,
      duplicatedNote.description,
      duplicatedNote.tag,
      duplicatedNote.attachments || [],
      duplicatedNote.images || [],
      duplicatedNote.todoItems || []
    );
  };

  // Export note functionality
  const exportNote = (note, format = 'txt') => {
    let content = `Title: ${note.title}\n\n`;
    content += `Description: ${note.description}\n\n`;
    if (note.tag) content += `Tags: ${note.tag}\n\n`;
    if (note.todoItems && note.todoItems.length > 0) {
      content += `Todo Items:\n`;
      note.todoItems.forEach((item, index) => {
        content += `${index + 1}. ${item.completed ? '✓' : '○'} ${item.text}\n`;
      });
    }
    content += `\nCreated: ${new Date(note.createdAt || note.date).toLocaleString()}`;
    content += `\nLast Modified: ${new Date(note.updatedAt || note.date).toLocaleString()}`;

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${note.title}.${format}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // Print note functionality
  const printNote = (note) => {
    const printWindow = window.open('', '_blank');
    let todoHtml = '';
    
    if (note.todoItems && note.todoItems.length > 0) {
      todoHtml = `
        <h3>Todo Items:</h3>
        <ul style="list-style: none; padding-left: 0;">
          ${note.todoItems.map(item => 
            `<li>
              <input type="checkbox" ${item.completed ? 'checked' : ''} disabled> 
              ${item.text}
            </li>`
          ).join('')}
        </ul>
      `;
    }

    printWindow.document.write(`
      <html>
        <head>
          <title>${note.title}</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 20px; }
            h1 { color: #333; border-bottom: 2px solid #333; }
            h3 { color: #666; }
            .meta { color: #888; font-size: 12px; margin-top: 20px; }
          </style>
        </head>
        <body>
          <h1>${note.title}</h1>
          <div>${note.description}</div>
          ${note.tag ? `<p><strong>Tags:</strong> ${note.tag}</p>` : ''}
          ${todoHtml}
          <div class="meta">
            <p>Created: ${new Date(note.createdAt || note.date).toLocaleString()}</p>
            <p>Last Modified: ${new Date(note.updatedAt || note.date).toLocaleString()}</p>
          </div>
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.print();
  };

  return (
    <NoteContext.Provider value={{ 
      notes, 
      addNote, 
      deleteNote, 
      editNote, 
      getNotes, 
      isInitialized,
      searchTerm,
      setSearchTerm,
      selectedTag,
      setSelectedTag,
      sortBy,
      setSortBy,
      getAllTags,
      getFilteredNotes,
      duplicateNote,
      exportNote,
      printNote,
      undo,
      redo,
      undoStack,
      redoStack,
      noteStats,
      calculateStats
    }}>
      {props.children}
    </NoteContext.Provider>
  );
};

export default NoteState;
